import * as T from 'three';
import {ISLAND_LANDMARKS,CLOUD_COLORS,LOOKOUT_SEAT} from './layout.js';
function owner(){const materials=new Map();return{mat(color){if(!materials.has(color))materials.set(color,new T.MeshStandardMaterial({color,roughness:.95}));return materials.get(color);}};}
function add(parent,geometry,material,name,position,scale=[1,1,1]){geometry.computeBoundingBox();geometry.computeBoundingSphere();const mesh=new T.Mesh(geometry,material);mesh.name=name;mesh.position.fromArray(position);mesh.scale.fromArray(scale);parent.add(mesh);return mesh;}
/** Cheap non-interactive silhouettes; no rooms, controllers, lights or timers. */
export function buildIslandScenery(){const root=new T.Group();root.name='island-connections.scenery';root.userData.excludeOverview=true;const{mat}=owner();const observatory=new T.Group();observatory.name='island-connections.observatory';observatory.position.fromArray(ISLAND_LANDMARKS.observatory.anchor);root.add(observatory);
 const cylinder=(parent,name,top,bottom,height,color,p,scale)=>add(parent,new T.CylinderGeometry(top,bottom,height,12),mat(color),name,p,scale);
 cylinder(observatory,'remote.observatory.sand',3.8,4.2,.32,'#ead8ac',[0,-.20,0],[1,1,.94]);cylinder(observatory,'remote.observatory.land',3.7,3.8,.15,'#b8c89a',[0,.035,0],[1,1,.94]);cylinder(observatory,'remote.observatory.drum',1.7,1.77,1.55,'#f8e9ce',[0,.87,0]);cylinder(observatory,'remote.observatory.dome-rim',1.79,1.79,.14,'#8db7b4',[0,1.72,0]);add(observatory,new T.SphereGeometry(1.77,12,6,0,Math.PI*2,0,Math.PI/2),mat('#8db7b4'),'remote.observatory.dome',[0,1.79,0],[1,.90,1]);add(observatory,new T.BoxGeometry(.025,.75,.48),mat('#647b7d'),'remote.observatory.door',[-1.722,.48,0]);
 const castle=new T.Group();castle.name='island-connections.cloud-castle';castle.position.fromArray(ISLAND_LANDMARKS.cloudCastle.anchor);root.add(castle);const puff=new T.SphereGeometry(1,12,8);for(const[i,[x,z,sx,sz,y,sy]]of [[-2.4,-1.5,2.2,2.4,-.45,.70],[0,-2.2,2.6,2.3,-.30,.60],[2.1,-1,2.3,2.6,-.55,.40],[-2.3,1.2,2.2,2.5,-.38,.65],[.3,1.9,2.9,2.5,-.55,.55],[2.7,1.2,2.1,2.2,-.30,.55]].entries())add(castle,puff,mat(i%2?CLOUD_COLORS.light:CLOUD_COLORS.shade),'remote.castle.cloud.'+i,[x,y,z],[sx,sy,sz]);
 for(const z of[-2,2]){cylinder(castle,'remote.castle.tower.'+z,.71,.8,1.74,'#f8e9ce',[0,.77,z]);cylinder(castle,'remote.castle.roof.'+z,0,.97,1.05,'#dca5ae',[0,2.15,z]);}
 const arch=add(castle,new T.TorusGeometry(1.20,.18,5,12,Math.PI),mat('#f8e9ce'),'remote.castle.arch',[0,.48,0]);arch.rotation.y=Math.PI/2;for(const z of[-1.2,1.2])add(castle,new T.BoxGeometry(.36,.55,.36),mat('#f8e9ce'),'remote.castle.arch-foot.'+z,[0,.20,z]);root.updateMatrixWorld(true);return root;}
function polygon(points){const s=new T.Shape();points.forEach(([x,z],i)=>i?s.lineTo(x,-z):s.moveTo(x,-z));s.closePath();const g=new T.ShapeGeometry(s);g.rotateX(-Math.PI/2);return g;}
/** Paint lies on existing supported paths and creates no collision footprint. */
export function buildIslandLookoutCues(){const root=new T.Group();root.name='island-connections.floor-cues';const{mat}=owner();const paint=mat('#587f80'),cream=mat('#f4e9cf'),cloud=mat(CLOUD_COLORS.light);for(const material of[paint,cream,cloud]){material.polygonOffset=true;material.polygonOffsetFactor=-1;material.polygonOffsetUnits=-1;}const flat=(parent,g,m,name,x,z,y=.052)=>add(parent,g,m,name,[x,y,z]);
 function arrow(x,z,name){const g=polygon([[-.32,-.065],[.1,-.065],[.1,-.17],[.35,0],[.1,.17],[.1,.065],[-.32,.065]]);g.translate(0,.0002,0);return flat(root,g,paint,name,x,z);}
 const marker=new T.Group();marker.name='island-connections.lookout-marker';marker.position.set(LOOKOUT_SEAT.at.x,0,LOOKOUT_SEAT.at.z);root.add(marker);const disc=new T.CircleGeometry(.5,24);disc.rotateX(-Math.PI/2);disc.translate(0,.0002,0);flat(marker,disc,cream,'lookout.compass',0,0).scale.set(.98,1,.52);
 const hull=polygon([[-.33,.07],[-.09,.07],[-.15,.16],[-.28,.16]]);flat(marker,hull,paint,'lookout.boat',0,0,.053);flat(marker,polygon([[-.24,.045],[-.24,-.17],[-.09,.045]]),paint,'lookout.sail',0,0,.053);
 const circle=new T.CircleGeometry(.10,12);circle.rotateX(-Math.PI/2);for(const[x,z,s]of[[.13,-.015,1],[.23,-.075,1.05],[.32,-.005,.85]])flat(marker,circle,cloud,'lookout.cloud',x,z,.0535).scale.set(s,1,s);arrow(14.85,6.3,'island-connections.lookout-arrow');arrow(1.5,3.1,'island-connections.square-arrow');flat(root,polygon([[-.23,-.075],[.23,-.075],[.14,.075],[-.14,.075]]),paint,'island-connections.square-boat',1.23,2.8,.052);flat(root,polygon([[-.22,-.035],[-.035,-.035],[-.13,-.20],[-.035,-.20],[.095,-.035],[.24,-.035],[.24,.035],[.095,.035],[-.035,.20],[-.13,.20],[-.035,.035],[-.22,.035]]),paint,'island-connections.square-plane',1.74,2.8,.052);return root;}
